    /*function to add tbl user shift*/
    function add_tbl_shift_time($shift_id,$params)
    { 
        $param['master_id'] = $params['updated_by'];
        $param['shift_id'] = $shift_id;
        $param['start_time'] = date("H:i:s", strtotime($params['master']));
        $param['app_time'] = date("H:i:s", strtotime($params['app_time']));
        $param['data_entry_operator'] = date("H:i:s", strtotime($params['data_entry_operator']));
        $this->db->insert('user_shift_timings',$param);
        return $this->db->insert_id();
    }
    
