        $this->db->join('tbl_shift', 'user_shift_timings.shift_id = tbl_shift.id', 'left');
		$this->db->order_by('user_shift_timings.id', 'asc');
        $this->db->where('user_shift_timings.master_id', '1');
        $this->db->or_where('user_shift_timings.master_id', $id);
        $this->db->where('tbl_shift.is_active', '1');
        $this->db->where('tbl_shift.open_date >=', date('Y-m-d'));
        $query = $this->db->get();
        return $query->result_array();
    }
    public function delete_shift_with_timing($usershift_timing_id) {
        // Get the shift ID from user_shift_timings table
        $this->db->select('shift_id');
        $this->db->from('user_shift_timings');
        $this->db->where('id', $usershift_timing_id);
        $query = $this->db->get();
        $result = $query->row();

        if ($result) {
            $shift_id = $result->shift_id;

            // Begin transaction to ensure both deletions succeed or fail together
            $this->db->trans_begin();

            // Delete from user_shift_timings table
            $this->db->where('id', $usershift_timing_id);
            $this->db->delete('user_shift_timings');

            // Delete the related record in tbl_shift using the shift ID
            $this->db->where('id', $shift_id);
            $this->db->delete('tbl_shift');

            // Check for successful completion of both queries
            if ($this->db->trans_status() === FALSE) {
                // Rollback if there’s an issue
                $this->db->trans_rollback();
                return false;
            } else {
                // Commit if successful
                $this->db->trans_commit();
                return true;
            }
        } else {
            // If no record is found, return false
            return false;
        }
    }
